#!/usr/bin/env python3
"""同等ロジック複製の対照実験.

字面 grep は test fixture / コメント / 文字列リテラルまで拾うため、
実行可能な Python ロジック (AST の関数定義と呼出し) だけを同じ方法で数える。
陽性対照 = harness 側、陰性側 = dev-graph production Python。
"""
import ast
import json
import sys
from pathlib import Path

IDENTS = ["run_chunk", "compile_docset"]


def scan(files):
    result = {i: {"defs": [], "calls": [], "attr_calls": []} for i in IDENTS}
    parse_errors = []
    for f in files:
        try:
            tree = ast.parse(f.read_text(encoding="utf-8"), filename=str(f))
        except SyntaxError as exc:
            parse_errors.append(f"{f}: {exc}")
            continue
        for node in ast.walk(tree):
            if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)) and node.name in IDENTS:
                result[node.name]["defs"].append(f"{f}:{node.lineno}")
            if isinstance(node, ast.Call):
                fn = node.func
                if isinstance(fn, ast.Name) and fn.id in IDENTS:
                    result[fn.id]["calls"].append(f"{f}:{node.lineno}")
                elif isinstance(fn, ast.Attribute) and fn.attr in IDENTS:
                    result[fn.attr]["attr_calls"].append(f"{f}:{node.lineno}")
    return result, parse_errors


def collect(root: Path, exclude_parts=()):
    out = []
    for f in sorted(root.rglob("*.py")):
        parts = set(f.parts)
        if "__pycache__" in parts:
            continue
        if any(x in parts for x in exclude_parts):
            continue
        out.append(f)
    return out


def main():
    wt = Path(sys.argv[1])
    harness = wt / "plugins" / "system-spec-harness"
    devgraph = wt / "plugins" / "dev-graph"

    harness_files = collect(harness)
    # 陰性側: dev-graph の production Python のみ (tests/ と tests/fixtures/ を除外)
    dg_files = collect(devgraph, exclude_parts=("tests", "fixtures"))

    h_res, h_err = scan(harness_files)
    d_res, d_err = scan(dg_files)

    report = {
        "method": "python ast: FunctionDef/AsyncFunctionDef 名一致 + Call(Name/Attribute) 名一致",
        "identifiers": IDENTS,
        "positive_control": {
            "root": str(harness),
            "files_scanned": len(harness_files),
